let api;
const ui={veeView:'open',veeUtility:'All utilities',veeQuery:'',filters:false,selectedReads:new Set(),category:'My Assigned Cases',exceptionStatus:'Open',exceptionQuery:'',sort:'age',selectedCase:null,compact:false,historyOpen:false};
const readRows=[
 {index:0,scheduled:'09/27/2026',overdue:4,mru:'Whitby Gas · Central (G-021)',registerLabel:'Gas Register',reason:'Periodic Meter Reading (01)',type:'Automatic estimation - SAP (03)',validation:'3 estimations (+2)',diagnosis:'Permissible number of estimations exceeded (03)',current:0,expected:28,unit:'CCF',register:1240,previous:1240,expectedRegister:1268,upper:1640,hardHold:false},
 {index:1,scheduled:'09/27/2026',overdue:4,mru:'Whitby Water · North (W-014)',registerLabel:'Water Register',reason:'Periodic Meter Reading (01)',type:'Automatic meter reading (01)',validation:'Upper tolerance exceeded',diagnosis:'Consumption exceeds expected quantity by 256% (01)',current:342,expected:96,unit:'m³',register:1846,previous:1504,expectedRegister:1600,upper:1648,hardHold:false},
 {index:2,scheduled:'09/29/2026',overdue:2,mru:'Whitby Electric · East (E-009)',registerLabel:'Electricity Register',reason:'Periodic Meter Reading (01)',type:'Manual meter reading (02)',validation:'Register went backwards',diagnosis:'Register result is below the last released reading (04)',current:-120,expected:760,unit:'kWh',register:6720,previous:6840,expectedRegister:7600,upper:7980,hardHold:true}
];
