const clarificationCases=[
 {id:'100004201',category:'Billing Outsorts',text:'High bill amount — consumption review',index:1,age:5,status:'Open',substatus:'001',subtext:'Review billing amount',job:'BILL_20261001',interval:'Monthly',assignee:'Unassigned',priority:'High',reason:'The sample billing amount exceeds its comparison threshold.',next:'Review the billing document and record a release decision.',amount:362,events:['Billing document outsorted by amount check.']},
 {id:'100004202',category:'Invoice Outsorts',text:'Invoice total exceeds release threshold',index:0,age:4,status:'Assigned',substatus:'002',subtext:'Awaiting invoice review',job:'INV_20261001',interval:'Monthly',assignee:'Demo operator',priority:'High',reason:'The invoice is held for a total-value review.',next:'Check the linked billing and print documents, then release or refer.',amount:418,events:['Invoice outsort created.','Assigned to Demo operator.']},
 {id:'100004203',category:'Field Work',text:'Special meter read — access required',index:3,age:3,status:'Assigned',substatus:'010',subtext:'Visit to be scheduled',job:'FIELD_MR',interval:'Once',assignee:'Demo operator',priority:'Medium',reason:'A no-access result requires a coordinated site visit.',next:'Schedule the visit and record the field outcome.',orderId:'FO-000189',events:['Field order FO-000189 created following no access.']},
 {id:'100004204',category:'Meter Read Follow-Up',text:'AMI communication failure — investigate',index:4,age:2,status:'Open',substatus:'003',subtext:'Check remote collection',job:'AMI_20261001',interval:'Daily',assignee:'Unassigned',priority:'Low',reason:'The meter did not report in the collection window.',next:'Check the meter and decide whether a field order is needed.',events:['Meter-read follow-up created.']},
 {id:'100004205',category:'Billing Errors',text:'Billing block — implausible read unresolved',index:2,age:2,status:'Open',substatus:'004',subtext:'Meter reading correction',job:'BILL_20261001',interval:'Monthly',assignee:'Unassigned',priority:'High',reason:'The current register is below the previous released register.',next:'Resolve the meter reading before retrying the billing handoff.',events:['Billing hold linked to register regression.']},
 {id:'100004206',category:'Bill Print Errors',text:'Print document output requires review',index:1,age:1,status:'Open',substatus:'005',subtext:'Review output request',job:'PRINT_20261001',interval:'Monthly',assignee:'Unassigned',priority:'Medium',reason:'The sample print-output request has failed.',next:'Review the print document and record the follow-up.',events:['Output review case created.']}
];
const $=s=>document.querySelector(s);
const number=v=>new Intl.NumberFormat('en-CA',{maximumFractionDigits:3}).format(v);
const closed=c=>c.status==='Completed';
const readFor=index=>readRows.find(r=>r.index===index);
function xbutton(label,act,extra=''){return `<button type="button" data-x-act="${act}" ${extra}>${label}</button>`;}
function selectedReadRows(){return readRows.filter(r=>ui.selectedReads.has(r.index));}
function readMatches(){return readRows.filter(r=>{const c=api.cases[r.index],done=api.state.resolved.has(c.id);return(ui.veeView==='all'||(ui.veeView==='released'?done:!done))&&(ui.veeUtility==='All utilities'||c.utility===ui.veeUtility)&&`${c.id} ${c.account} ${c.address} ${device(c)} ${r.validation} ${r.mru}`.toLowerCase().includes(ui.veeQuery.toLowerCase());});}
function caseMatches(){return clarificationCases.filter(c=>(ui.category==='My Assigned Cases'?c.assignee==='Demo operator':c.category===ui.category)&&(ui.exceptionStatus==='All'||(ui.exceptionStatus==='Completed'?closed(c):!closed(c)))&&`${c.id} ${c.text} ${c.assignee} ${api.cases[c.index].account} ${api.cases[c.index].address}`.toLowerCase().includes(ui.exceptionQuery.toLowerCase())).sort((a,b)=>ui.sort==='age'?b.age-a.age:a.id.localeCompare(b.id));}
function device(c){return 'DM26'+c.utility[0]+'0'+c.id.slice(2);}
function nativeHeader(page){return api.sapTransactionHeader(page);}
function statusbar(text){return `<footer class="fiori-status"><span class="sap-square green"></span><span>${text}</span><span class="spacer"></span><span>Sample data · Session only</span></footer>`;}
function veeBody(){const rows=readMatches();return rows.length?rows.map(r=>{const c=api.cases[r.index],done=api.state.resolved.has(c.id),value=done?(c.readDetails?.releasedRegister??r.register)-r.previous:r.current;return `<tbody class="vee-record ${done?'released':''}"><tr class="vee-main-row"><td><input type="checkbox" data-read-select="${r.index}" ${ui.selectedReads.has(r.index)?'checked':''} ${done?'disabled':''} aria-label="Select meter ${device(c)}"></td><td><span class="${done?'vee-released':'vee-overdue'}">${done?'Released':`${r.overdue} Days<br>Overdue`}</span><br>${r.scheduled}</td><td><button class="fiori-link" data-read-open="${r.index}">${device(c)}</button><br><span class="vee-doc-id">MR-2026-${c.id.slice(2)}</span><br><span>METER;${c.utility==='Gas'?'GAS':c.utility==='Water'?'WTR':'ELEC'};${r.unit}</span></td><td>001<br>${r.registerLabel}</td><td><input type="checkbox" disabled aria-label="No additional meter reading reasons"></td><td>${r.mru}</td><td>${r.reason}</td><td>${r.type}</td><td>${xbutton('›','open-read',`data-index="${r.index}" class="row-chevron" aria-label="Open ${device(c)}"`)}</td></tr><tr class="vee-detail-row"><td></td><td colspan="8"><div class="vee-line"><span>Independent Validation:</span><div>${r.validation}<br>${r.diagnosis}</div></div><div class="vee-line"><span>Consumption/Demand:</span><div>Current: &nbsp;${number(value)} ${r.unit}<br>Expected: ${number(r.expected)} ${r.unit}</div></div></td></tr></tbody>`;}).join(''):`<tbody><tr><td colspan="9" class="fiori-empty">No meter readings match the selected filters.</td></tr></tbody>`;}
function veePage(){const count=readMatches().length,selected=selectedReadRows().filter(r=>!api.state.resolved.has(api.cases[r.index].id)).length;return `<section class="fiori-shell vee-shell">${nativeHeader('vee')}<section class="vee-variant"><div class="vee-variant-line">${xbutton(`Standard <span class="chevron-down"></span>`,'filters','aria-expanded="'+ui.filters+'"')}<div class="vee-views"><label class="sr-only" for="vee-view">Read status</label><select id="vee-view"><option value="open" ${ui.veeView==='open'?'selected':''}>Open</option><option value="released" ${ui.veeView==='released'?'selected':''}>Released</option><option value="all" ${ui.veeView==='all'?'selected':''}>All statuses</option></select></div></div><div class="vee-filter-summary">Filtered By: ${ui.veeView==='open'?'Open implausible readings':ui.veeView==='released'?'Released readings':'All readings'}${ui.veeUtility==='All utilities'?'':' · '+api.esc(ui.veeUtility)}</div><div class="vee-filters" ${ui.filters?'':'hidden'}><label>Utility<select id="vee-utility">${['All utilities','Gas','Water','Electric'].map(v=>`<option ${ui.veeUtility===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Device, account or address<input id="vee-query" type="search" value="${api.esc(ui.veeQuery)}" placeholder="Search readings"></label>${xbutton('Clear filters','clear-vee')}</div><button class="vee-filter-toggle" data-x-act="filters" aria-label="${ui.filters?'Hide':'Show'} filters"><span class="chevron-down ${ui.filters?'up':''}"></span></button></section><div class="vee-list"><div class="vee-list-toolbar"><h2>Meter Readings (<span id="vee-count">${count}</span>)</h2><span class="spacer"></span><span class="vee-selected" id="vee-selected">${selected?selected+' selected':''}</span>${xbutton('Create Field Service Order','field-from-read',`id="vee-field-order" ${selected===1?'':'disabled'}`)}${xbutton('Release','release-reads',`id="vee-release" ${selected?'':'disabled'}`)}${xbutton(api.icon('download'),'export-reads','class="fiori-icon" title="Export current list" aria-label="Export current list"')}</div><div class="vee-scroll"><table class="vee-table"><thead><tr><th><input type="checkbox" id="select-all-reads" aria-label="Select all open readings" ${selected&&selected===readMatches().filter(r=>!api.state.resolved.has(api.cases[r.index].id)).length?'checked':''}></th><th>Sched.<br>Reading Date</th><th>Device</th><th>Register</th><th>More MR<br>Reasons</th><th>Meter Reading Unit</th><th>Meter reading reason</th><th>Meter reading type</th><th></th></tr></thead>${veeBody()}</table></div></div>${statusbar('Meter reading results · '+(ui.veeView==='open'?'Implausible':'Review history'))}</section>`;}
function refreshReadList(){const table=$('.vee-table');if(!table)return;for(const body of [...table.tBodies])body.remove();table.insertAdjacentHTML('beforeend',veeBody());$('#vee-count').textContent=readMatches().length;updateReadSelection();}
function updateReadSelection(){const open=readMatches().filter(r=>!api.state.resolved.has(api.cases[r.index].id)),selected=selectedReadRows().filter(r=>!api.state.resolved.has(api.cases[r.index].id)).length;if($('#vee-release'))$('#vee-release').disabled=!selected;if($('#vee-field-order'))$('#vee-field-order').disabled=selected!==1;if($('#vee-selected'))$('#vee-selected').textContent=selected?selected+' selected':'';const all=$('#select-all-reads');if(all){const n=open.filter(r=>ui.selectedReads.has(r.index)).length;all.checked=open.length>0&&n===open.length;all.indeterminate=n>0&&n<open.length;}}
function releaseReads(indices,method='accept'){
 const rows=indices.map(readFor).filter(Boolean).filter(r=>!api.state.resolved.has(api.cases[r.index].id));
 if(!rows.length)return {ok:false,message:'Select an open meter reading first.'};
 if(method==='accept'&&rows.some(r=>r.hardHold))return {ok:false,message:'Register regression needs a corrected value or estimate. Open that reading first.'};
 for(const r of rows){const c=api.cases[r.index];c.readDetails.releasedRegister=method==='estimate'?r.expectedRegister:r.register;c.readDetails.method=method;c.readDetails.status=method==='estimate'?'Estimated and released':'Released as read';api.state.resolved.add(c.id);ui.selectedReads.delete(r.index);for(const linked of clarificationCases.filter(item=>item.index===r.index&&item.category==='Billing Errors'&&!closed(item))){linked.substatus='006';linked.subtext='Meter reading released';linked.reason='The reading has been released; the billing handoff is ready for review.';linked.next='Review the billing order and record the case outcome.';linked.events.push('Linked meter reading released in the VEE worklist.');}}
 return {ok:true,message:`${rows.length} reading${rows.length===1?'':'s'} released in the preview.`};
}
function openReading(index){if(!api.canReviewMeterRead(index)){api.openSapTransaction('read-query');return;}const r=readFor(index);if(!r)return;const c=api.cases[index],done=api.state.resolved.has(c.id);api.state.selected=index;api.openDialog('Meter reading · '+device(c),`<div class="read-review"><div class="read-review-context">${api.esc(c.address)} · ${c.account}</div><div class="read-review-fields"><span>Scheduled reading date</span><b>${r.scheduled}</b><span>Register / unit</span><b>001 / ${r.unit}</b><span>Previous register</span><b>${number(r.previous)}</b><span>Current register</span><b>${number(done?c.readDetails.releasedRegister:r.register)}</b><span>Expected register</span><b>${number(r.expectedRegister)}</b><span>Status</span><b>${done?api.esc(c.readDetails.status||'Released'):'Implausible'}</b></div><section class="read-review-diagnosis"><h3>Independent Validation</h3><p>${r.validation}<br>${r.diagnosis}</p></section><div class="read-review-actions">${done?'':xbutton('Release as read','release-one',`data-index="${index}" ${r.hardHold?'disabled title="Correct or estimate the regressed reading first"':''}`)+xbutton('Estimate & release','estimate-one',`data-index="${index}"`)}</div><p class="small">Sample actions stay in this preview. Release does not create an invoice.</p></div>`);}
function exceptionBody(){const rows=caseMatches();return rows.length?rows.map(c=>`<tr class="clarification-row ${ui.selectedCase===c.id?'is-selected':''}" data-clarification="${c.id}" tabindex="0" aria-selected="${ui.selectedCase===c.id}"><td><span class="clarification-status ${closed(c)?'complete':''}"></span></td><td class="${closed(c)?'':'overdue-cell'}">${closed(c)?'—':c.age+' d'}</td><td>${c.id}</td><td>${api.esc(c.text)}</td><td>${c.status}</td><td>${c.substatus}</td><td>${api.esc(c.subtext)}</td><td>${c.job}</td><td>${c.interval}</td><td>DEMO_ISU</td><td>${api.esc(c.assignee)}</td></tr>`).join(''):`<tr><td colspan="11" class="fiori-empty">No ${ui.exceptionStatus==='Open'?'open ':''}cases in ${api.esc(ui.category)}${ui.exceptionQuery?' match this search':''}.</td></tr>`;}
// Field service orders are linked session fixtures. Dispatch is an explicit preview action.
const fieldDrafts=new Map();
let activeFieldDraft=null,fieldOrderSequence=1;
const fieldChoices={orderType:['FS01 · Field service','FS02 · Urgent field service'],plant:['WH01 · Whitby'],plannerGroup:['MR · Meter services','FO · Field operations'],workCenter:['METER-GAS','METER-WATER','METER-ELECTRIC'],activityType:['Special meter read','Meter investigation','Meter exchange','Access investigation'],priority:['1 · High','2 · Normal','3 · Low']};
const fieldRequirements={orderType:['Order type','header'],shortText:['Order description','header'],plant:['Planning plant','header'],plannerGroup:['Planner group','header'],workCenter:['Main work center','header'],activityType:['Activity type','header'],startDate:['Basic start','header'],finishDate:['Basic finish','header'],priority:['Priority','header'],longText:['Notification long text','header'],operation:['Operation','operations'],duration:['Estimated duration','operations'],accessNotes:['Access / dispatch instructions','partner']};
function beginFieldOrder(index,caseId=null){
 const source=caseId?clarificationCases.find(c=>c.id===caseId):null;if(!api.cases[index])return;
 const existingId=source?.orderId||source?.linkedFieldOrderId||(!caseId?api.cases[index].fieldOrderId:null);
 let draft=existingId?[...fieldDrafts.values()].find(d=>d.orderId===existingId):null;
 const key=caseId?'case:'+caseId:'vee:'+index;
 draft=draft||fieldDrafts.get(key);if(!draft&&source&&closed(source))return;
 if(!draft){draft={key,index,caseId,returnRoute:api.state.lastSapRoute,tab:'header',orderId:source?.orderId||null,linkedCaseId:source?.category==='Field Work'?source.id:null,stage:'Draft',errors:{},saved:false,values:{orderType:'',shortText:'',plant:'',plannerGroup:'',workCenter:'',responsible:'',activityType:'',startDate:'',finishDate:'',priority:'',longText:'',operation:'',duration:'',contactName:'',contactPhone:'',accessNotes:'',downtime:false,breakdown:false},components:[]};fieldDrafts.set(key,draft);}
 draft.returnRoute=api.state.lastSapRoute;activeFieldDraft=draft;api.state.selected=index;go('sap/field-order');
}
export function hasFieldOrderDraft(){return !!activeFieldDraft;}
function fieldControl(name,label,{type='text',required=false,wide=false}={}){
 const d=activeFieldDraft,value=d.values[name]??'',locked=d.stage!=='Draft',attrs=`name="${name}" id="fo-${name}" data-field-name="${name}" ${locked?'disabled':''} ${required?'required':''} ${d.errors[name]?'aria-invalid="true" aria-describedby="fo-error-'+name+'"':''}`;
 const control=fieldChoices[name]?`<select ${attrs}><option value=""> </option>${fieldChoices[name].map(v=>`<option ${v===value?'selected':''}>${v}</option>`).join('')}</select>`:type==='textarea'?`<textarea ${attrs} rows="${name==='longText'?9:4}" maxlength="1600">${api.esc(value)}</textarea>`:`<input ${attrs} type="${type}" value="${api.esc(value)}" ${type==='date'?`min="${api.state.asOf}"`:type==='number'?'min="1" step="1"':'maxlength="120"'}>`;
 return `<div class="fo-field ${wide?'fo-wide':''}"><label for="fo-${name}">${label}${required?' <span class="fo-required">*</span>':''}</label>${control}${d.errors[name]?`<small id="fo-error-${name}" class="fo-field-error">${api.esc(d.errors[name])}</small>`:''}</div>`;
}
function fieldOrderPage(){
 const d=activeFieldDraft;if(!d)return exceptionsPage();const customer=api.cases[d.index],locked=d.stage!=='Draft',sys=d.stage==='Draft'?'CRTD':d.stage==='Ready for dispatch'?'REL':d.stage==='Dispatched'?'REL DISP':'TECO',title=d.stage==='Draft'?'Create Field Service Order':'Display Field Service Order';
 let body='';
 if(d.tab==='header')body=`<div class="fo-columns"><div>${guiGroup('Person responsible',`${fieldControl('plannerGroup','PlannerGrp',{required:true})}${fieldControl('plant','Planning plant',{required:true})}${fieldControl('workCenter','Mn.wk.ctr',{required:true})}${fieldControl('responsible','Person Resp.')}${fieldControl('activityType','PMActType',{required:true})}`)}${guiGroup('Dates',`${fieldControl('startDate','Bsc start',{type:'date',required:true})}${fieldControl('finishDate','Basic fin.',{type:'date',required:true})}${fieldControl('priority','Priority',{required:true})}<div class="fo-checks"><label><input type="checkbox" data-field-name="downtime" ${d.values.downtime?'checked':''} ${locked?'disabled':''}> Operational downtime</label><label><input type="checkbox" data-field-name="breakdown" ${d.values.breakdown?'checked':''} ${locked?'disabled':''}> Breakdown</label></div>`)}${guiGroup('Reference object',`${guiField('Func. Loc.','710000'+customer.id.slice(2))}${guiField('Equipment',device(customer))}${guiField('Contract Acct',customer.account)}${guiField('Premise',customer.address)}`)}</div><div>${guiGroup('Notification Longtext',fieldControl('longText','Longtext',{type:'textarea',required:true,wide:true}))}${guiGroup('Source reference',`${guiField('Origin',d.caseId?'Clarification case':'Implausible meter reading')}${guiField('Reference',d.caseId||'MR-2026-'+customer.id.slice(2))}${guiField('Division',customer.utility)}`)}</div></div>`;
 if(d.tab==='operations')body=guiGroup('First operation',`<div class="fo-operation-number">Operation &nbsp; <span class="gui-code">0010</span></div>${fieldControl('operation','Operation text',{required:true})}${fieldControl('duration','Duration (minutes)',{type:'number',required:true})}${guiField('Control key','FIELD')}${guiField('Work center',d.values.workCenter||'Not assigned')}`);
 if(d.tab==='components')body=guiGroup('Components',`<div class="fo-component-scroll"><table class="fo-components"><thead><tr><th>Item</th><th>Component / description</th><th>Quantity</th><th>Unit</th><th></th></tr></thead><tbody>${d.components.map((c,i)=>`<tr><td>${String(i+1).padStart(4,'0')}</td><td><input aria-label="Component ${i+1}" data-field-component="${i}" data-component-key="description" value="${api.esc(c.description)}" ${locked?'disabled':''}></td><td><input aria-label="Quantity ${i+1}" type="number" min="1" data-field-component="${i}" data-component-key="quantity" value="${api.esc(c.quantity)}" ${locked?'disabled':''}></td><td><select aria-label="Unit ${i+1}" data-field-component="${i}" data-component-key="unit" ${locked?'disabled':''}>${['EA','M'].map(v=>`<option ${c.unit===v?'selected':''}>${v}</option>`).join('')}</select></td><td>${xbutton('Delete','fo-remove-component',`data-index="${i}" ${locked?'disabled':''}`)}</td></tr>`).join('')||'<tr><td colspan="5" class="fo-no-components">No components specified.</td></tr>'}</tbody></table></div>${d.errors.components?`<p class="fo-field-error">${d.errors.components}</p>`:''}<div class="gui-inline-actions">${xbutton('Add component','fo-add-component',`class="gui-yellow" ${locked?'disabled':''}`)}</div>`);
 if(d.tab==='partner')body=`<div class="fo-columns"><div>${guiGroup('Partner',`${fieldControl('contactName','Contact name')}${fieldControl('contactPhone','Telephone',{type:'tel'})}${guiField('Contract Acct',customer.account)}${guiField('Service address',customer.address)}`)}</div><div>${guiGroup('Access / Dispatch Instructions',fieldControl('accessNotes','Instructions',{type:'textarea',required:true,wide:true}))}</div></div>`;
 return `<section class="fiori-shell gui-case-shell fo-shell">${api.sapTransactionHeader('field-order','',title)}<form id="field-service-form" novalidate><div class="gui-transaction-toolbar"><button type="submit" data-field-save="release" ${locked?'disabled':''}>⚑ Release &amp; Save</button><button type="submit" data-field-save="draft" ${locked?'disabled':''}>▣ Save Draft</button>${xbutton('Dispatch','fo-dispatch',d.stage==='Ready for dispatch'?'':'disabled')}${xbutton('‹ Back to source','fo-back')}</div><div class="fo-scroll"><div class="fo-order-line">${fieldControl('orderType','Order',{required:true})}<span class="gui-value fo-order-id">${d.orderId||'New'}</span>${fieldControl('shortText','Description',{required:true})}</div><div class="fo-system-status">Sys.Status <span class="gui-value">${sys} &nbsp; ${d.stage}</span></div>${Object.keys(d.errors).length?'<div class="fo-validation" role="alert">Complete the highlighted fields before releasing this order for dispatch.</div>':''}<nav class="fo-tabs" aria-label="Order sections">${[['header','HeaderData'],['operations','Operations'],['components','Components'],['partner','Partner']].map(([id,label])=>`<button type="button" data-fo-tab="${id}" class="${d.tab===id?'active':''}" ${d.tab===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="fo-tab-body">${body}</div></div></form>${statusbar((d.orderId||'New field service order')+' · '+d.stage)}</section>`;
}
function validateFieldOrder(d){
 const errors={};for(const [key,[label]] of Object.entries(fieldRequirements))if(!String(d.values[key]??'').trim())errors[key]=label+' is required.';
 const dateOK=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;
 if(d.values.startDate&&(!dateOK(d.values.startDate)||d.values.startDate<api.state.asOf))errors.startDate='Choose a date on or after the run date.';
 if(d.values.finishDate&&(!dateOK(d.values.finishDate)||d.values.finishDate<d.values.startDate))errors.finishDate='Finish must be on or after the start date.';
 if(d.values.duration&&(!Number.isFinite(Number(d.values.duration))||Number(d.values.duration)<=0))errors.duration='Enter a positive duration.';
 for(const key of Object.keys(fieldChoices))if(d.values[key]&&!fieldChoices[key].includes(d.values[key]))errors[key]='Choose a valid '+fieldRequirements[key][0].toLowerCase()+'.';
 if(d.components.some(c=>!c.description.trim()||!Number.isFinite(Number(c.quantity))||Number(c.quantity)<=0||!['EA','M'].includes(c.unit)))errors.components='Each component needs a description, positive quantity and unit.';
 return errors;
}
function syncFieldOrder(d,stage){
 if(!d.orderId)d.orderId='FO-20261001-'+String(fieldOrderSequence++).padStart(4,'0');
 let fieldCase=clarificationCases.find(c=>c.id===d.linkedCaseId);
 if(!fieldCase){fieldCase={id:String(Math.max(...clarificationCases.map(c=>Number(c.id)))+1),category:'Field Work',text:d.values.shortText.trim()||'Field service order — draft',index:d.index,age:0,status:'Draft',substatus:'010',subtext:'Order form incomplete',job:'FIELD_SERVICE',interval:'Once',assignee:'Demo operator',priority:'Medium',reason:'Field work requested from '+(d.caseId?'clarification case '+d.caseId:'an implausible meter reading')+'.',next:'Complete and release the field service order.',events:[]};clarificationCases.push(fieldCase);d.linkedCaseId=fieldCase.id;}
 d.stage=stage;d.saved=true;fieldCase.orderId=d.orderId;fieldCase.workType=d.values.activityType||'Field service';fieldCase.text=d.values.shortText.trim()||fieldCase.text;fieldCase.priority=d.values.priority.startsWith('1')?'High':d.values.priority.startsWith('3')?'Low':'Medium';fieldCase.fieldReady=stage!=='Draft';fieldCase.dispatchStatus=stage;fieldCase.status=stage;fieldCase.visitDate=stage==='Draft'?undefined:d.values.startDate;fieldCase.substatus=stage==='Draft'?'010':stage==='Ready for dispatch'?'020':'030';fieldCase.subtext=stage;fieldCase.next=stage==='Draft'?'Complete the order form and release it for dispatch.':stage==='Ready for dispatch'?'Dispatch the released field service order.':'Record the field outcome when the work is complete.';fieldCase.events.push(d.orderId+' · '+stage+'.');
 const source=clarificationCases.find(c=>c.id===d.caseId);if(source&&source!==fieldCase){source.linkedFieldOrderId=d.orderId;source.events.push('Field order '+d.orderId+' · '+stage+'.');}
 api.cases[d.index].fieldOrderId=d.orderId;
}
function saveFieldOrder(mode){
 const d=activeFieldDraft;if(!d||d.stage!=='Draft')return false;
 d.errors=mode==='release'?validateFieldOrder(d):{};
 if(Object.keys(d.errors).length){const first=Object.keys(d.errors)[0];d.tab=fieldRequirements[first]?.[1]||'components';api.render();return false;}
 syncFieldOrder(d,mode==='release'?'Ready for dispatch':'Draft');api.render();api.toast(mode==='release'?'Field service order released and ready for dispatch.':'Draft saved. Complete the form before dispatch.');return true;
}
function dispatchFieldOrder(d=activeFieldDraft){if(!d||d.stage!=='Ready for dispatch'||Object.keys(validateFieldOrder(d)).length){api.toast('Complete and release the order before dispatch.');return false;}syncFieldOrder(d,'Dispatched');api.render();api.toast('Field service order dispatched in the preview.');return true;}
function captureFieldInput(t){const d=activeFieldDraft;if(!d||d.stage!=='Draft')return;if(t.dataset.fieldName){d.values[t.dataset.fieldName]=t.type==='checkbox'?t.checked:t.value;delete d.errors[t.dataset.fieldName];}if(t.dataset.fieldComponent!==undefined){const c=d.components[Number(t.dataset.fieldComponent)];if(c&&['description','quantity','unit'].includes(t.dataset.componentKey)){c[t.dataset.componentKey]=t.value;delete d.errors.components;}}}
function guiField(label,value,extra=''){return `<div class="gui-field"><span>${label}</span><span class="gui-value ${extra}">${api.esc(value)}</span></div>`;}
function guiGroup(title,body,extra=''){return `<section class="gui-group ${extra}"><h3>${title}</h3><div class="gui-group-body">${body}</div></section>`;}
function createdDate(c){const date=new Date(api.state.asOf+'T00:00:00Z');date.setUTCDate(date.getUTCDate()-c.age);return date.toLocaleDateString('en-US',{timeZone:'UTC',month:'2-digit',day:'2-digit',year:'numeric'});}
function caseDetail(c){
 const customer=api.cases[c.index],field=!!c.orderId,done=closed(c),canRelease=c.category.includes('Outsorts'),partner=c.index===0?'1100000101':'110000'+customer.id.slice(2),categoryCode=String(Math.max(1,categories.indexOf(c.category))).padStart(2,'0'),disabled=done?'disabled':'',processing=done?'Completed':c.status==='Assigned'?'In Processing':c.status,reasonCode=c.id.slice(-3);
 const completeDisabled=done||(field&&(!c.fieldReady||c.dispatchStatus!=='Dispatched'))?'disabled':'';
 return `<section class="fiori-shell gui-case-shell" aria-label="Clarification Case Detail">${api.sapTransactionHeader('exceptions',c.id)}<nav class="gui-transaction-toolbar" aria-label="Case transactions">${xbutton('‹ Back to List','close-case')}${xbutton(api.icon('billing')+' Display Billing','case-orders')}</nav><div class="gui-case-scroll"><div class="gui-case-content"><div class="gui-case-header"><div><div class="gui-field"><span>Clar.Case Cat.</span><span class="gui-code">${categoryCode}</span><span class="gui-inline-text">${c.category}</span></div>${guiField('Clarif. Case',c.id)}</div><div>${guiField('Created on',createdDate(c))}${guiField('Time','01:05:00')}${guiField('Created By',c.job)}</div></div>
 ${guiGroup('Master Data',`<div class="gui-master-grid"><div>${guiField('Business partn.',partner)}${guiField('Contract Acct',customer.account)}${guiField('Installation','710000'+customer.id.slice(2))}</div><div>${guiField('Premise',customer.address)}${guiField('Division',customer.utility)}</div></div>`)}
 ${guiGroup('Clarification Reason',`<div class="gui-field gui-reason"><span>Clarific.Reason</span><span class="gui-code">${reasonCode}</span><span class="gui-reason-text">${api.esc(c.text)}</span></div><p class="gui-reason-description">${api.esc(c.reason)}</p>`)}
 <div class="gui-primary-actions">${xbutton('<span class="gui-action-check">✓</span> Clarif. Case Completed','case-complete',`class="gui-yellow" ${completeDisabled} ${field&&(!c.fieldReady||c.dispatchStatus!=='Dispatched')?'title="Complete and dispatch the field service order first"':''}`)}${xbutton(`<span class="gui-action-stop">✖</span> ${c.invoiceHold?'Remove Invoice Hold':'Do Not Invoice Account'}`,'case-invoice-hold',`class="gui-yellow" ${disabled}`)}</div>
 ${guiGroup('Status/lock information',`<div class="gui-status-grid"><div class="gui-status-fields">${guiField('Last Processing Status',c.subtext,'gui-select-display')}${guiField('Status',processing,'gui-select-display')}<div class="gui-lock-row"><label><input type="checkbox" disabled ${!done&&c.assignee==='Demo operator'?'checked':''}>Active lock</label>${guiField('Valid to',done?'—':'10/01/2026')}</div><div class="gui-lock-row"><label><input type="checkbox" disabled ${c.resubmitOn?'checked':''}>Resub. active</label><label class="gui-date-label" for="case-resubmit">Resubmission on <input id="case-resubmit" type="date" value="${c.resubmitOn||''}" min="${api.state.asOf}" ${disabled}></label></div></div><div class="gui-status-right">${xbutton('▤ &nbsp; History','case-history','class="gui-yellow"')}${guiField('Last Processor',c.assignee)}${guiField('Invoicing Lock',c.invoiceHold?'Account held':'No lock')}</div></div>`)}
 ${field?guiGroup('Field Work',`<div class="gui-master-grid"><div>${guiField('Order',c.orderId)}${guiField('Work type',c.workType||'Special meter read')}</div><div>${guiField('Visit date',c.visitDate||'Not scheduled')}${guiField('Order status',done?'Completed':c.dispatchStatus||'Draft')}</div></div><div class="gui-inline-actions">${xbutton('Open field service order','new-field-order','class="gui-yellow"')}${xbutton('Dispatch','case-dispatch',`class="gui-yellow" ${c.dispatchStatus==='Ready for dispatch'?'':'disabled'}`)}${xbutton(c.visitDate?'Reschedule visit':'Schedule visit','schedule-visit',`class="gui-yellow" ${done||!c.fieldReady?'disabled':''}`)}${xbutton('Complete field work','complete-field',`class="gui-yellow" ${completeDisabled}`)}</div>`):''}
 ${guiGroup('Processing',`<div class="gui-master-grid"><div>${guiField('Priority',c.priority)}${guiField('Assigned To',c.assignee)}</div><div>${guiField('Substatus',c.substatus+' · '+c.subtext)}${c.amount?guiField('Amount under review',api.money(c.amount)):''}</div></div><div class="gui-field gui-next"><span>Next Action</span><span>${api.esc(done?'Clarification completed.':c.next)}</span></div><div class="gui-inline-actions">${xbutton('Take ownership','take-case',`class="gui-yellow" ${done||c.assignee==='Demo operator'?'disabled':''}`)}${xbutton('Add note','case-note',`class="gui-yellow" ${disabled}`)}${!field?xbutton(c.linkedFieldOrderId?'Open field service order':'Create Field Service Order','new-field-order',`class="gui-yellow" ${disabled}`):''}${canRelease?'<span class="gui-processing-hint">Complete the case to record the outsort release.</span>':''}</div>`)}
 ${ui.historyOpen?guiGroup('Processing History',`<table class="gui-history-table"><thead><tr><th>Step</th><th>Activity</th></tr></thead><tbody>${c.events.map((e,i)=>`<tr><td>${i+1}</td><td>${api.esc(e)}</td></tr>`).join('')}</tbody></table>`,'gui-history'):''}
 </div></div>${statusbar('Clarification case '+c.id+' · '+processing)}</section>`;
}
function exceptionsPage(){const current=caseMatches();return `<section class="fiori-shell clarification-shell">${nativeHeader('exceptions')}<div class="clarification-main-toolbar">${xbutton(ui.compact?'Comfortable layout':'Compact layout','layout')}${xbutton('Update Clarification Case List','refresh-cases')}${xbutton('Export list','export-cases')}</div><div class="clarification-layout"><aside class="clarification-sidebar"><div>Billing</div><nav aria-label="Clarification categories">${categories.map(cat=>`<button data-category="${cat}" class="${ui.category===cat?'active':''}" ${ui.category===cat?'aria-current="page"':''}>${cat}</button>`).join('')}</nav></aside><section class="clarification-main"><div class="clarification-title">${api.esc(ui.category)}</div><div class="clarification-table-toolbar">${xbutton(api.icon('search'),'focus-search','class="native-tool" title="Find a case" aria-label="Find a case"')}${xbutton(ui.sort==='age'?'Oldest first':'Case number','sort-cases','class="native-tool sort-tool" title="Change sort order"')}<label class="sr-only" for="exception-status">Status</label><select id="exception-status">${['Open','Completed','All'].map(v=>`<option ${ui.exceptionStatus===v?'selected':''}>${v}</option>`).join('')}</select><input type="search" id="exception-query" placeholder="Case, text, account…" value="${api.esc(ui.exceptionQuery)}" aria-label="Find clarification case"><span class="spacer"></span><span id="exception-count">${current.length} cases</span></div><div class="clarification-table-scroll ${ui.compact?'compact':''}"><table class="clarification-table"><thead><tr><th></th><th>Overdue</th><th>Case</th><th>Clarification Case Text</th><th>Status</th><th>Substatus</th><th>Substatus Text</th><th>Job</th><th>Interval</th><th>Logical system</th><th>Assignee</th></tr></thead><tbody id="exception-body">${exceptionBody()}</tbody></table></div></section></div>${statusbar('Clarification Case List')}</section>`;}
function refreshCases(){if($('#exception-body'))$('#exception-body').innerHTML=exceptionBody();if($('#exception-count'))$('#exception-count').textContent=caseMatches().length+' cases';}
function selectedCase(){return clarificationCases.find(c=>c.id===ui.selectedCase);}
function noteDialog(mode){const c=selectedCase();if(!c||closed(c))return;const field=mode==='schedule',title=mode==='hold'?'Do Not Invoice Account':mode==='unhold'?'Remove Invoice Hold':mode==='complete-case'?'Complete Clarification Case':mode==='release'?'Release billing / invoice outsort':mode==='complete'?'Complete field work':field?'Schedule field visit':mode==='field'?'Create field order':'Case note / resolution';api.openDialog(title,`<form id="clarification-action-form" data-mode="${mode}" data-case-id="${c.id}" class="clarification-action-form"><p>${api.esc(c.text)} · ${c.id}</p>${field?`<label>Visit date<input type="date" name="visitDate" min="${api.state.asOf}" value="${c.visitDate||api.state.asOf}" required></label>`:''}${mode==='field'?`<label>Work type<select name="workType"><option>Special meter read</option><option>Meter investigation</option><option>Meter exchange</option></select></label>`:''}<label>${mode==='complete'?'Field outcome':mode==='release'?'Release reason':'Note'}<textarea name="note" required rows="3" maxlength="600" placeholder="Record the decision or next action"></textarea></label><div class="read-review-actions"><button type="submit">${field?'Schedule visit':mode==='field'?'Create order':mode==='release'?'Release outsort':mode==='complete'?'Complete work':mode==='complete-case'?'Complete case':mode==='hold'?'Hold account':mode==='unhold'?'Remove hold':'Save note'}</button>${api.btn('Cancel','close')}</div><p class="small">Preview only · No command is sent to SAP or field staff.</p></form>`);}
function exportCSV(name,headers,rows){const cell=v=>{let s=String(v??'');if(/^[=+@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const text=[headers,...rows].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function go(page){const hash=api.route(page,'experiment');if(location.hash===hash)api.render();else location.hash=hash;}
function openClarification(id){ui.selectedCase=id;ui.historyOpen=false;go('exceptions/'+id);}
function openBilling(index,tab='orders'){api.state.selected=index;const dlg=$('#dialog');if(dlg?.open)dlg.close();api.openSapTransaction(tab);}
function updateCase(c,mode,values){
 if(!c||closed(c))return {ok:false,message:'This case is already completed.'};
 const note=String(values.note||'').trim();if(!note)return {ok:false,message:'Enter a note before saving.'};
 if(mode==='complete'&&(!c.fieldReady||c.dispatchStatus!=='Dispatched'))return {ok:false,message:'Complete and dispatch the field service order first.'};
 if(mode==='schedule'&&!c.fieldReady)return {ok:false,message:'Complete and release the field service order first.'};
 if(mode==='complete'&&!c.visitDate)return {ok:false,message:'Schedule the field visit first.'};
 if(mode==='schedule'&&(!/^\d{4}-\d{2}-\d{2}$/.test(values.visitDate||'')||values.visitDate<api.state.asOf))return {ok:false,message:'Choose a visit date on or after the run date.'};
 if(c.invoiceHold&&['release','complete','complete-case'].includes(mode))return {ok:false,message:'Remove the invoice hold before completing this case.'};
 c.assignee='Demo operator';
 if(mode==='hold'||mode==='unhold'){c.invoiceHold=mode==='hold';c.status='Assigned';c.substatus=c.invoiceHold?'030':'002';c.subtext=c.invoiceHold?'Account held from invoicing':'In review';c.events.push((c.invoiceHold?'Invoice hold applied: ':'Invoice hold removed: ')+note);}
 else if(mode==='complete-case'){c.status='Completed';c.substatus='090';c.subtext='Clarification completed';c.events.push('Clarification completed: '+note);}
 else if(mode==='release'){c.status='Completed';c.substatus='090';c.subtext='Outsort released';c.events.push('Outsort released: '+note);}
 else if(mode==='complete'){c.status='Completed';c.substatus='090';c.subtext='Field work completed';c.events.push('Field work completed: '+note);c.dispatchStatus='Completed';const d=[...fieldDrafts.values()].find(d=>d.orderId===c.orderId);if(d)d.stage='Completed';}
 else if(mode==='schedule'){c.status='Scheduled';c.visitDate=values.visitDate;c.substatus='020';c.subtext='Visit scheduled';c.events.push('Visit scheduled for '+values.visitDate+': '+note);const d=[...fieldDrafts.values()].find(d=>d.orderId===c.orderId);if(d){d.values.startDate=values.visitDate;if(d.values.finishDate<values.visitDate)d.values.finishDate=values.visitDate;}}
 else if(mode==='field'){c.orderId='FO-'+c.id.slice(-6);c.workType=values.workType||'Special meter read';c.category='Field Work';c.status='Assigned';c.substatus='010';c.subtext='Visit to be scheduled';c.next='Schedule the visit and record the field outcome.';c.events.push((values.workType||'Field work')+' order '+c.orderId+' created: '+note);}
 else{c.status=values.resolve?'Completed':'Assigned';c.substatus=values.resolve?'090':'002';c.subtext=values.resolve?'Resolved':'In review';c.events.push((values.resolve?'Resolved: ':'Note: ')+note);}
 return {ok:true,message:'Case '+c.id+' updated in the preview.'};
}
export function reviewMeterRead(index){if(!readFor(index))return false;openReading(index);return true;}
export function hasInvoiceHold(index){return clarificationCases.some(c=>c.index===index&&c.invoiceHold);}
export function exceptionWorkspace(page,id=''){if(page==='field-order')return fieldOrderPage();if(page==='vee')return veePage();const c=clarificationCases.find(c=>c.id===id);if(c){ui.selectedCase=c.id;api.state.selected=c.index;return caseDetail(c);}return exceptionsPage();}
export function installExceptionWorkspaces(dependencies){api=dependencies;
 for(const r of readRows){api.cases[r.index].readDetails={register:r.register,previous:r.previous,expected:r.expectedRegister,upper:r.upper,scheduled:r.scheduled,unit:r.unit,releasedRegister:r.register,status:'Implausible'};}
 document.addEventListener('click',ev=>{
  const orderTab=ev.target.closest('[data-fo-tab]');if(orderTab&&activeFieldDraft){activeFieldDraft.tab=orderTab.dataset.foTab;api.render();return;}
  const category=ev.target.closest('[data-category]');if(category){if(category.dataset.category==='MR Implausibles'){go('vee');return;}ui.category=category.dataset.category;ui.selectedCase=null;api.render();return;}
  const row=ev.target.closest('[data-clarification]');if(row){openClarification(row.dataset.clarification);return;}
  const read=ev.target.closest('[data-read-open]');if(read){openReading(Number(read.dataset.readOpen));return;}
  const button=ev.target.closest('[data-x-act]');if(!button)return;const act=button.dataset.xAct,index=Number(button.dataset.index);

  if(act==='field-from-read'){const rows=selectedReadRows().filter(r=>!api.state.resolved.has(api.cases[r.index].id));if(rows.length===1)beginFieldOrder(rows[0].index);else api.toast('Select one implausible reading to create a field service order.');}
  if(act==='fo-back'&&activeFieldDraft)location.hash=activeFieldDraft.returnRoute;
  if(act==='fo-dispatch')dispatchFieldOrder();
  if(act==='case-dispatch'){const c=selectedCase(),d=[...fieldDrafts.values()].find(d=>d.orderId===c?.orderId);if(d)dispatchFieldOrder(d);}
  if(act==='fo-add-component'&&activeFieldDraft?.stage==='Draft'){activeFieldDraft.components.push({description:'',quantity:'1',unit:'EA'});api.render();}
  if(act==='fo-remove-component'&&activeFieldDraft?.stage==='Draft'){activeFieldDraft.components.splice(index,1);api.render();}
  if(act==='filters'){ui.filters=!ui.filters;api.render();}
  if(act==='clear-vee'){ui.veeUtility='All utilities';ui.veeQuery='';ui.veeView='open';api.render();}
  if(act==='open-read')openReading(index);
  if(act==='release-reads'||act==='release-one'||act==='estimate-one'){const result=releaseReads(act==='release-reads'?[...ui.selectedReads]:[index],act==='estimate-one'?'estimate':'accept');api.toast(result.message);if(result.ok){$('#dialog')?.close();api.render();}}
  if(act==='reading-document'){const dlg=$('#dialog');if(dlg?.open)dlg.close();api.openSapRelated('reads');}
  if(act==='focus-search'){if(api.state.sapTransaction==='vee'){ui.filters=true;api.render();$('#vee-query')?.focus();}else $('#exception-query')?.focus();}
  if(act==='export-reads'){exportCSV('implausible-meter-readings-sample.csv',['Case','Device','Account','Date','Validation','Current','Expected','Unit','Status'],readMatches().map(r=>{const c=api.cases[r.index];return[c.id,device(c),c.account,r.scheduled,r.validation,api.state.resolved.has(c.id)?c.readDetails.releasedRegister-r.previous:r.current,r.expected,r.unit,api.state.resolved.has(c.id)?'Released':'Implausible'];}));}
  if(act==='export-cases')exportCSV('clarification-cases-sample.csv',['Case','Category','Text','Status','Assignee','Overdue days','Field order'],caseMatches().map(c=>[c.id,c.category,c.text,c.status,c.assignee,c.age,c.orderId||'']));
  if(act==='layout'){ui.compact=!ui.compact;api.render();}
  if(act==='refresh-cases'){api.render();api.toast('Sample clarification case list updated.');}
  if(act==='sort-cases'){ui.sort=ui.sort==='age'?'case':'age';api.render();}
  if(act==='close-case')go('exceptions');
  if(act==='case-history'){ui.historyOpen=!ui.historyOpen;api.render();$('.gui-history')?.scrollIntoView({block:'nearest'});}
  if(act==='case-contract'){const c=selectedCase();if(c)openBilling(c.index,'contract');}
  if(act==='case-orders'){const c=selectedCase();if(c)openBilling(c.index,'orders');}
  if(act==='case-complete'){const c=selectedCase();if(c)noteDialog(c.category.includes('Outsorts')?'release':c.orderId?'complete':'complete-case');}
  if(act==='case-invoice-hold'){const c=selectedCase();if(c)noteDialog(c.invoiceHold?'unhold':'hold');}
  if(act==='case-billing'){const c=selectedCase();if(c)openBilling(c.index,c.category==='Invoice Outsorts'?'invoice':c.category==='Bill Print Errors'?'invoice':c.category==='Billing Outsorts'?'document':'orders');}
  if(act==='case-read-document'){const c=selectedCase();if(c)openBilling(c.index,'reads');}
  if(act==='case-reading'){const c=selectedCase();if(c)openReading(c.index);}
  if(act==='take-case'){const c=selectedCase();if(c&&!closed(c)){c.assignee='Demo operator';c.status='Assigned';c.events.push('Assigned to Demo operator.');api.render();api.toast('Case assigned to you in the preview.');}}
  if(act==='release-outsort')noteDialog('release');if(act==='schedule-visit')noteDialog('schedule');if(act==='complete-field')noteDialog('complete');if(act==='new-field-order'){const c=selectedCase();if(c)beginFieldOrder(c.index,c.id);}if(act==='case-note')noteDialog('note');
 });
 document.addEventListener('change',ev=>{const t=ev.target;captureFieldInput(t);
  if(t.id==='case-resubmit'){const c=selectedCase();if(c&&!closed(c)){if(t.value&&(!t.validity.valid||t.value<api.state.asOf)){t.reportValidity();return;}c.resubmitOn=t.value;c.events.push(t.value?'Resubmission scheduled for '+t.value+'.':'Resubmission date cleared.');api.render();api.toast('Resubmission updated in the preview.');}return;}
  if(t.id==='vee-view'){ui.veeView=t.value;ui.selectedReads.clear();api.render();}
  if(t.id==='vee-utility'){ui.veeUtility=t.value;ui.selectedReads.clear();api.render();}
  if(t.hasAttribute?.('data-read-select')){const index=Number(t.dataset.readSelect);t.checked?ui.selectedReads.add(index):ui.selectedReads.delete(index);updateReadSelection();}
  if(t.id==='select-all-reads'){for(const r of readMatches().filter(r=>!api.state.resolved.has(api.cases[r.index].id)))t.checked?ui.selectedReads.add(r.index):ui.selectedReads.delete(r.index);refreshReadList();}
  if(t.id==='exception-status'){ui.exceptionStatus=t.value;ui.selectedCase=null;api.render();}
 });
 document.addEventListener('input',ev=>{captureFieldInput(ev.target);if(ev.target.id==='vee-query'){ui.veeQuery=ev.target.value;ui.selectedReads.clear();refreshReadList();}if(ev.target.id==='exception-query'){ui.exceptionQuery=ev.target.value;refreshCases();}});
 document.addEventListener('keydown',ev=>{const row=ev.target.closest('[data-clarification]');if(row&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();openClarification(row.dataset.clarification);}});
 document.addEventListener('submit',ev=>{if(ev.target.id==='field-service-form'){ev.preventDefault();saveFieldOrder(ev.submitter?.dataset.fieldSave||'release');return;}if(ev.target.id!=='clarification-action-form')return;ev.preventDefault();const form=ev.target,values=Object.fromEntries(new FormData(form)),c=clarificationCases.find(c=>c.id===form.dataset.caseId),result=updateCase(c,form.dataset.mode,values);api.toast(result.message);if(result.ok){$('#dialog').close();api.render();}});
}
